from urllib.parse import urlparse, urljoin
import re
from typing import Optional

def validate_url(url: str, allowed_schemes: list[str] = None) -> bool:
    """EGRR_PATTERN: Validate URL format and scheme."""
    if not url or not isinstance(url, str):
        return False

    allowed_schemes = allowed_schemes or ['http', 'https']

    try:
        result = urlparse(url.strip())
        return all([
            result.scheme in allowed_schemes,
            result.netloc,  # Has domain
            len(url) <= 2048  # Reasonable max length
        ])
    except Exception:
        return False

def sanitize_url(url: str) -> Optional[str]:
    """EGRR_PATTERN: Sanitize and normalize URL."""
    if not url:
        return None

    url = url.strip()

    # Add scheme if missing
    if not url.startswith(('http://', 'https://')):
        url = 'https://' + url

    if not validate_url(url):
        return None

    return url

def is_safe_redirect_url(url: str, allowed_hosts: list[str]) -> bool:
    """EGRR_PATTERN: Validate redirect URL to prevent open redirect."""
    if not url:
        return False

    # Allow relative URLs
    if url.startswith('/'):
        return not url.startswith('//')

    try:
        parsed = urlparse(url)
        return parsed.netloc.lower() in [h.lower() for h in allowed_hosts]
    except Exception:
        return False

def extract_domain(url: str) -> Optional[str]:
    """EGRR_PATTERN: Extract domain from URL safely."""
    try:
        parsed = urlparse(url)
        return parsed.netloc.lower() if parsed.netloc else None
    except Exception:
        return None
